import java.util.*;

public class StringBasics {

    // 1. 判断回文串（忽略非字母数字，忽略大小写）
    public boolean isPalindrome(String s) {
        int left = 0, right = s.length() - 1;
        while (left < right) {
            while (left < right && !Character.isLetterOrDigit(s.charAt(left))) left++;
            while (left < right && !Character.isLetterOrDigit(s.charAt(right))) right--;
            if (Character.toLowerCase(s.charAt(left)) != Character.toLowerCase(s.charAt(right))) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }

    // 2. 最长回文子串（中心扩展法，O(n^2)）
    public String longestPalindrome(String s) {
        if (s == null || s.length() < 2) return s;
        int start = 0, maxLen = 1;
        for (int i = 0; i < s.length(); i++) {
            int len1 = expand(s, i, i);      // 奇数长度回文
            int len2 = expand(s, i, i + 1);   // 偶数长度回文
            int len = Math.max(len1, len2);
            if (len > maxLen) {
                maxLen = len;
                start = i - (len - 1) / 2;
            }
        }
        return s.substring(start, start + maxLen);
    }

    private int expand(String s, int l, int r) {
        while (l >= 0 && r < s.length() && s.charAt(l) == s.charAt(r)) {
            l--; r++;
        }
        return r - l - 1;  // 循环结束时 l 和 r 各多走一步
    }

    // 3. KMP：构建 next 数组
    private int[] buildNext(String pat) {
        int m = pat.length();
        int[] next = new int[m];
        int len = 0; // 当前最长相等前后缀长度
        for (int i = 1; i < m; i++) {
            while (len > 0 && pat.charAt(i) != pat.charAt(len)) {
                len = next[len - 1]; // 回退到更短的前缀
            }
            if (pat.charAt(i) == pat.charAt(len)) {
                len++;
            }
            next[i] = len;
        }
        return next;
    }

    // 4. KMP：匹配
    public int kmpSearch(String text, String pat) {
        if (pat.isEmpty()) return 0;
        int[] next = buildNext(pat);
        int j = 0; // pattern 指针
        for (int i = 0; i < text.length(); i++) {
            while (j > 0 && text.charAt(i) != pat.charAt(j)) {
                j = next[j - 1]; // 失配：pattern 指针跳 next
            }
            if (text.charAt(i) == pat.charAt(j)) {
                j++;
            }
            if (j == pat.length()) {
                return i - j + 1; // 匹配成功
            }
        }
        return -1; // 未找到
    }

    // 5. 字符串转整数（atoi）
    public int myAtoi(String s) {
        int idx = 0, sign = 1, result = 0;
        while (idx < s.length() && s.charAt(idx) == ' ') idx++;
        if (idx < s.length() && (s.charAt(idx) == '+' || s.charAt(idx) == '-')) {
            sign = s.charAt(idx) == '-' ? -1 : 1;
            idx++;
        }
        while (idx < s.length() && Character.isDigit(s.charAt(idx))) {
            int digit = s.charAt(idx) - '0';
            if (result > (Integer.MAX_VALUE - digit) / 10) {
                return sign == 1 ? Integer.MAX_VALUE : Integer.MIN_VALUE;
            }
            result = result * 10 + digit;
            idx++;
        }
        return result * sign;
    }
}
